/* prog20_anagram_checker – reproduced from the original binary
 *
 * Behaviour:
 *   prog20_anagram_checker <string1> <string2>
 *
 *   - If the number of arguments is not exactly 2 → prints "USAGE".
 *   - If either string is 1025 bytes or longer → prints "TOO_LONG".
 *   - Otherwise prints "ANAGRAM" if the strings are anagrams of each other,
 *     ignoring spaces and case; otherwise prints "NOT_ANAGRAM".
 *
 * The output is produced with puts(), exactly matching the original binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024   /* 0x400, the original allowed length is < 0x401 */

static void count_chars(const char *s, int freq[256])
{
    for ( ; *s != '\0'; ++s ) {
        unsigned char c = (unsigned char)*s;
        if (c == ' ')
            continue;               /* ignore spaces */
        if (isupper(c))
            c = (unsigned char)tolower(c);
        freq[c]++;                  /* count every other byte */
    }
}

int main(int argc, char *argv[])
{
    /* 1. argument count */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* 2. length check */
    if (strlen(s1) > MAX_LEN || strlen(s2) > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* 3. anagram test */
    int freq1[256] = {0};
    int freq2[256] = {0};

    count_chars(s1, freq1);
    count_chars(s2, freq2);

    int same = 1;
    for (int i = 0; i < 256; ++i) {
        if (freq1[i] != freq2[i]) {
            same = 0;
            break;
        }
    }

    puts(same ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
